    const back = at(0.95, Math.PI, 0.22), pack = new THREE.Group(); pack.position.set(0, back.y, back.z); hips.add(pack); const yel = M("#f2c230", 0.4, { metalness: 0.25, clearcoat: 0.6 });
    add(pack, new THREE.BoxGeometry(0.66 * BW, 0.74, 0.12), M("#9aa3ad", 0.45, { metalness: 0.6 }), [0, 0, 0.06]);
