      x.strokeStyle = shade(jk, -0.5); x.lineWidth = 5; for (const s of [-1, 1]) { x.beginPath(); x.moveTo(X(s * v(1.16)), Y(1.16)); x.lineTo(X(0), Y(0.44)); x.stroke(); }   // the lapels' edges
      x.strokeStyle = shade(jk, 0.18); x.lineWidth = 3; for (const s of [-1, 1]) { x.beginPath(); x.moveTo(X(s * (v(1.16) + 0.12)), Y(1.16)); x.lineTo(X(s * (v(0.86) + 0.1)), Y(0.86)); x.lineTo(X(s * v(0.78)), Y(0.8)); x.stroke(); }   // the lapels' fold and notch
      x.fillStyle = "#dcd8cf"; for (const s of [-1, 1]) { x.beginPath(); x.moveTo(X(0), Y(1.12)); x.lineTo(X(s * 0.3), Y(1.18)); x.lineTo(X(s * 0.16), Y(0.96)); x.fill(); }   // the shirt's collar points
      x.fillStyle = tie; x.beginPath(); x.moveTo(X(-0.075), Y(1.14)); x.lineTo(X(0.075), Y(1.14)); x.lineTo(X(0.05), Y(1.03)); x.lineTo(X(0.13), Y(0.58)); x.lineTo(X(0), Y(0.49)); x.lineTo(X(-0.13), Y(0.58)); x.lineTo(X(-0.05), Y(1.03)); x.fill();   // the knot and the blade
